#include <cassert>
#include <climits>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <string>
#include <stdexcept>
static_assert(INT_MIN == (-2147483647 - 1) && INT_MAX == 2147483647, "32-bit int required");
int divide_without_mul_div(int a, int b) {
    if (b == 0) throw std::invalid_argument("division by zero");
    // 부호를 바꾸기 전에 넓힙니다. INT_MIN의 양수 크기도 int64_t에 들어갑니다.
    std::int64_t remaining = static_cast<std::int64_t>(a);
    std::int64_t divisor = static_cast<std::int64_t>(b);
    const bool negative = (a < 0) != (b < 0);
    if (remaining < 0) remaining = -remaining;
    if (divisor < 0) divisor = -divisor;
    std::int64_t quotient = 0;
    while (remaining >= divisor) {
        std::int64_t chunk = divisor, count = 1;
        // chunk+chunk 대신 차이를 비교해 불필요한 큰 중간 합을 만들지 않습니다.
        while (chunk <= remaining - chunk) { chunk += chunk; count += count; }
        remaining -= chunk; quotient += count;
    }
    if (negative) quotient = -quotient;
    if (quotient < INT_MIN || quotient > INT_MAX) throw std::overflow_error("quotient overflow");
    return static_cast<int>(quotient);
}
// 정수 하나는 공백으로 나눈 토큰 전체여야 합니다. 1+2를 두 수로 읽지 않습니다.
bool read_integer(std::istream& input, long long& value) {
    std::string token;
    if (!(input >> token)) return false;
    const std::size_t first = (token[0] == '+' || token[0] == '-') ? 1 : 0;
    if (first == token.size()) return false;
    for (std::size_t i = first; i < token.size(); ++i)
        if (token[i] < '0' || token[i] > '9') return false;
    std::istringstream parser(token);
    parser >> value;
    return !parser.fail() && parser.eof();
}

int main(){
 // ASCII 십진 32비트 정수 두 개만 받습니다.
 long long a=0,b=0;if((!read_integer(std::cin,a)||!read_integer(std::cin,b))||a<INT_MIN||a>INT_MAX||b<INT_MIN||b>INT_MAX)return 1;
 std::cin>>std::ws;if(std::cin.peek()!=std::char_traits<char>::eof())return 1;
 try{std::cout<<divide_without_mul_div(static_cast<int>(a),static_cast<int>(b))<<'\n';}
 catch(const std::invalid_argument&){return 1;}catch(const std::overflow_error&){return 1;}
 return std::cout?0:1;
}
